204		      {"index": 1, "term": 1, "command": "set balance=10"},
205		      {"index": 2, "term": 1, "command": "set balance=999"},
206		      {"index": 3, "term": 2, "command": "set receipt=ok"}
207		    ], "leaderCommit": 3}
208		  ]
209		}`
210		var stdout, stderr bytes.Buffer
211		code := runReplicateIO(strings.NewReader(input), &stdout, &stderr)
212		if code != 0 {
213			t.Fatalf("exit code = %d, stderr=%s", code, stderr.String())
214		}
215		if stderr.Len() != 0 {
216			t.Fatalf("replication rejection is normal output, stderr must be empty, got %q", stderr.String())
217		}
218		var out mevwatch.ReplicateOutput
219		if err := json.Unmarshal(stdout.Bytes(), &out); err != nil {
220			t.Fatalf("stdout is not valid JSON: %v\n%s", err, stdout.String())
221		}
222		if len(out.Results) != 1 {
223			t.Fatalf("expected 1 result, got %+v", out.Results)
224		}
225		result := out.Results[0]
226		if result.Accepted || result.Reason != mevwatch.ReasonCommandConflictSameTerm {
227			t.Fatalf("expected same-term command conflict rejection, got %+v", result)
228		}
229		if result.Term != 2 {
230			t.Fatalf("higher term must survive the rejection, got %d", result.Term)
231		}
232		if result.CommittedIndex != 1 {
233			t.Fatalf("rejection must not move committedIndex, got %d", result.CommittedIndex)
234		}
235		if result.Conflict != nil {
236			t.Fatalf("command conflict must not carry a prev-log-mismatch hint: %+v", result.Conflict)
237		}
238		if result.AppliedIndex == nil || *result.AppliedIndex != 1 {
239			t.Fatalf("appliedIndex should stay at 1, got %+v", result.AppliedIndex)
240		}
241		if result.ApplyError != nil {
242			t.Fatalf("rejected commands must not produce an applyError: %+v", result.ApplyError)
